<!-- Generated by Trae Work -->
<script setup>
/**
 * 角色状态编辑器（基础设定模块）
 *
 * 新增：4 套角色状态模板一键套用
 *   - 修真·仙侠状态
 *   - 西幻·冒险者状态
 *   - 谍战·权谋状态
 *   - 末日·废土状态
 */
import { computed } from 'vue'
import ChoicesEditor from '@/components/admin/ChoicesEditor.vue'
import { useChoicesStore } from '@/stores/choices'
import {
  getCharacterStatusTemplateList,
  getCharacterStatusTemplate,
} from '@/data/presetChoicesTemplates'

const choices = useChoicesStore()

const items = computed(() => choices.characterStatus)

/** 只读保护：数据库枚举值（后端 Character.STATUS_CHOICES） */
const readOnlyKeys = ['active', 'missing', 'dead', 'sealed', 'retired', 'unknown']

/** 模板列表 */
const templates = computed(() => getCharacterStatusTemplateList())
function getTemplateFn(key) {
  return getCharacterStatusTemplate(key)
}

function onSave(list) {
  choices.characterStatus.splice(0, choices.characterStatus.length, ...list)
}
</script>

<template>
  <ChoicesEditor
    title="角色状态"
    subtitle="角色卡片上的状态徽标。修改后所有角色列表、详情页的状态显示会同步变化。📜 已内置 4 套成熟模板可一键套用。"
    icon="👁"
    accent-color="emerald"
    :items="items"
    :read-only-keys="readOnlyKeys"
    :templates="templates"
    :get-template-fn="getTemplateFn"
    key-placeholder="例：active / missing / dead（英文、数字、下划线）"
    @save="onSave"
  />
</template>
